<template><div class="page"><h2 class="page-title">储蓄目标与预算底线</h2><p class="muted">告诉系统你从哪里出发、想在什么时候存到多少，以及哪些生活开支必须保留。</p><EmptyGuide v-if="ready&&!hasTransactions" description="还没有可用的消费数据" hint="请先导入账单并查看消费分析，再设置目标。" action="/bills" action-text="导入账单"/><template v-else><div class="card section"><h3>1. 设置目标</h3><el-form label-position="top" :model="form"><div class="grid form-grid"><el-form-item label="现在可用于目标的存款"><el-input v-model="form.current" inputmode="decimal"><template #append>元</template></el-input></el-form-item><el-form-item label="希望达到的存款"><el-input v-model="form.target" inputmode="decimal"><template #append>元</template></el-input></el-form-item><el-form-item label="从哪天开始规划"><el-date-picker v-model="form.start" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="希望哪天完成"><el-date-picker v-model="form.end" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="预计每月可支配收入"><el-input v-model="form.income" inputmode="decimal"><template #append>元</template></el-input><small class="field-help">请填工资或其他可靠收入；微信转入不会自动当作收入。</small></el-form-item></div><el-button type="primary" :loading="saving" @click="create">保存目标，继续设置预算底线</el-button></el-form></div>
<div v-if="goalId" class="card section"><h3>2. 设置每周预算底线</h3><p class="muted">最低预算表示你希望无论如何保留的周支出，不是系统认定的“最低生活标准”。固定类别会保持该金额。</p><el-table :data="constraints"><el-table-column prop="name" label="类别"/><el-table-column label="每周至少保留"><template #default="s"><el-input v-model="s.row.minimum" inputmode="decimal"><template #append>元</template></el-input></template></el-table-column><el-table-column label="每周最多（可选）"><template #default="s"><el-input v-model="s.row.maximum" inputmode="decimal"><template #append>元</template></el-input></template></el-table-column><el-table-column label="保持固定"><template #default="s"><el-switch v-model="s.row.fixed" @change="s.row.maximum=s.row.fixed?s.row.minimum:s.row.maximum"/></template></el-table-column><el-table-column label="你能接受的调整"><template #default="s"><el-select v-model="s.row.adjustability" :disabled="s.row.fixed"><el-option v-for="o in adjustabilityOptions" :key="o.value" v-bind="o"/></el-select></template></el-table-column></el-table><div class="next-step"><span>保存后即可比较正常消费与储蓄目标需要的预算。</span><el-button type="primary" :loading="savingConstraints" @click="saveConstraints">保存并去生成预算</el-button></div></div></template></div></template>
<script setup>
import { onMounted,reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { api } from '../api/client.js';import { yuanToMinor } from '../utils/money.js';import { adjustabilityOptions,validateGoal } from '../utils/forms.js';import EmptyGuide from '../components/EmptyGuide.vue'
const router=useRouter(),today=new Date().toISOString().slice(0,10),next=new Date(Date.now()+180*86400000).toISOString().slice(0,10),form=reactive({current:'5000',target:'12000',start:today,end:next,income:'3000'}),constraints=ref([]),goalId=ref(),saving=ref(false),savingConstraints=ref(false),ready=ref(false),hasTransactions=ref(false)
onMounted(async()=>{try{const [categories,dashboard]=await Promise.all([api.get('/categories'),api.get('/dashboard')]);hasTransactions.value=dashboard.workflow?.has_transactions;constraints.value=categories.items.map(c=>({category_code:c.code,name:c.name,minimum:'0',maximum:'',fixed:false,adjustability:'medium'}))}finally{ready.value=true}})
async function create(){let current,target,income;try{current=yuanToMinor(form.current);target=yuanToMinor(form.target);income=yuanToMinor(form.income||'0')}catch(e){return ElMessage.error(e.message)}const err=validateGoal({start_date:form.start,target_date:form.end,current_savings_minor:current,target_savings_minor:target});if(err)return ElMessage.error(err);saving.value=true;try{const r=await api.post('/goals',{current_savings_minor:current,start_date:form.start,target_date:form.end,target_savings_minor:target,income_assumptions:[{frequency:'monthly',amount_minor:income,start_date:form.start,end_date:form.end,expected_day:10}]});goalId.value=r.id;ElMessage.success('目标已保存，请确认每周预算底线')}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
async function saveConstraints(){savingConstraints.value=true;try{await api.put(`/goals/${goalId.value}/constraints`,{constraints:constraints.value.map(x=>({category_code:x.category_code,minimum_budget_minor:yuanToMinor(x.minimum||'0'),maximum_budget_minor:x.maximum===''?null:yuanToMinor(x.maximum),is_fixed:x.fixed,adjustability:x.fixed?'none':x.adjustability}))});ElMessage.success('预算底线已保存');router.push('/budgets')}catch(e){ElMessage.error(e.message)}finally{savingConstraints.value=false}}
</script>
